DROP TABLE IF EXISTS consult_message; CREATE TABLE consult_message (id VARCHAR(64) PRIMARY KEY COMMENT '消息ID', consult_id VARCHAR(64) COMMENT '咨询ID', sender_id VARCHAR(64) NOT NULL COMMENT '发送者ID', content TEXT NOT NULL COMMENT '消息内容', reply TEXT COMMENT 'AI回复内容', type VARCHAR(20) NOT NULL COMMENT '消息类型', status VARCHAR(20) DEFAULT 'PENDING' COMMENT '状态', create_time DATETIME NOT NULL COMMENT '创建时间', update_time DATETIME NOT NULL COMMENT '更新时间', FOREIGN KEY (sender_id) REFERENCES user(id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='咨询消息表'; 
